import {createComponentStore,storageKey} from '../data.mjs';
import {defaultDraft,createDraftStore,roles,eligible,calculateMaster,draftKey} from './model.mjs';
const $=s=>document.querySelector(s),form=$('#master-form'),field=k=>form.elements.namedItem(k),el=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;},money=v=>v===null||!Number.isFinite(v)?'Not calculated':new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP'}).format(v/100);
let draft,store,inventory=[],ready=false;
function populateRows(){for(const [group,keys] of Object.entries({bridge:['bridgePot','bridgeCap','bridgeBleed'],neck:['neckPot','neckCap','neckBleed'],hardware:['jack','toggle'],consumables:['cloth','braided','solder','heatShrink']})){
 const root=$('#rows-'+group);root.replaceChildren();for(const role of keys){const row=draft.rows.find(r=>r.role===role),meta=roles[role],section=el('div');section.className='master-row';section.dataset.role=role;
 const heading=el('label'),include=el('input');include.type='checkbox';include.name=role+'-include';include.checked=row.include;heading.append(include,document.createTextNode('Include '+meta.label));section.append(heading);
 const controls=el('div');controls.className='master-row-controls';const label=el('label','Component'),select=el('select');select.name=role+'-component';const empty=el('option','Select component');empty.value='';select.append(empty);const candidates=inventory.filter(p=>eligible(p,role));if(row.componentId&&!candidates.some(p=>p.id===row.componentId)){const old=inventory.find(p=>p.id===row.componentId),option=el('option',(old?.name||row.componentId)+' · unavailable');option.value=row.componentId;select.append(option);}for(const p of candidates){const option=el('option',p.name+' · '+p.sku);option.value=p.id;select.append(option);}select.value=row.componentId;label.append(select);
 const qtyLabel=el('label','Quantity'+(meta.unit?' ('+meta.unit+')':'')),qty=el('input');qty.name=role+'-quantity';qty.type='number';qty.min=meta.consumable?'.001':'1';qty.step=meta.consumable?'.001':'1';qty.value=row.quantity;qtyLabel.append(qty);const chargeLabel=el('label'),charge=el('input');charge.type='checkbox';charge.name=role+'-charge';charge.checked=row.charge;chargeLabel.append(charge,document.createTextNode('Apply kit add-on'));controls.append(label,qtyLabel,chargeLabel);section.append(controls);const note=el('p');note.id=role+'-detail';note.className='master-detail';section.append(note);root.append(section);
 }} }
function collect(){for(const key of ['reference','channel','basePrice','packaging','labourRate','labourMinutes','feePercent','feeFixed'])draft[key]=field(key).value;for(const row of draft.rows){row.include=field(row.role+'-include').checked;row.componentId=field(row.role+'-component').value;row.quantity=field(row.role+'-quantity').value;row.charge=field(row.role+'-charge').checked;}}
function render(){
 $('#ebay-fees').hidden=draft.channel!=='EBAY';for(const row of draft.rows){for(const suffix of ['component','quantity','charge'])field(row.role+'-'+suffix).disabled=!row.include;$('#'+row.role+'-detail').textContent='';}
 try{const result=calculateMaster(draft,inventory);$('#master-error').textContent='';$('#master-results').hidden=false;$('#kit-type').textContent=result.kitType;$('#master-warnings').replaceChildren(...result.warnings.map(w=>el('p',w)));if(!result.lines.length)$('#master-warnings').append(el('p','No components selected. Add the parts required before assessing this build.'));
 for(const line of result.lines){const item=line.component;$('#'+line.role+'-detail').textContent=(item?[item.manufacturer,...Object.entries(item.specs||{}).map(([k,v])=>k+': '+v)].filter(Boolean).join(' · ')+' | ':'')+'Unit: '+line.unit+' | Unit cost: '+money(line.internalUnitCost)+' | Parts: '+money(line.lineInternalCost)+' | Kit add-on: '+money(line.lineCustomerAddon)+(line.charge?' (saved '+money(line.savedKitPrice)+' covers '+line.kitPriceBasis+' units)':' (not charged)');}
 const c=result.costing,labels={partsCost:'Parts Cost',packaging:'Packaging Cost',marketplaceFee:'Marketplace Fee',labourRate:'Labour £/hour',labourCost:'Labour Cost',base:'Base Kit Price',customerAddons:'Customer Kit Add-ons',salePrice:'Calculated Sale Price',grossProfit:'Gross Profit',netProfit:'Net Profit After Labour'};const summary=$('#costing-values');summary.replaceChildren();for(const [key,label] of Object.entries(labels)){const row=el('div');row.append(el('dt',label),el('dd',money(c[key])));summary.append(row);}for(const [label,value] of [['Labour Time',c.minutes+' minutes'],['Gross Margin',c.grossMargin===null?'Not calculated':c.grossMargin.toFixed(2)+'%'],['Net Margin',c.netMargin===null?'Not calculated':c.netMargin.toFixed(2)+'%']]){const row=el('div');row.append(el('dt',label),el('dd',value));summary.append(row);}
 $('#stock-body').replaceChildren(...result.stock.map(s=>{const row=el('tr');row.append(el('th',s.name+' ('+s.unit+')'),el('td',String(s.required)),el('td',s.available===null?'Unknown':String(s.available)),el('td',s.after===null?'Unknown':s.shortfall?'Shortfall '+s.shortfall:String(s.after)));return row;}));$('#stock-empty').hidden=!!result.stock.length;
 }catch(error){$('#master-error').textContent=error.message;$('#master-results').hidden=true;}
}
function update(){if(!ready)return;collect();try{store.save(draft);$('#draft-status').textContent='Draft saved in this browser.';}catch(error){$('#draft-status').textContent=error.message;}render();}
form.addEventListener('submit',e=>e.preventDefault());form.addEventListener('input',update);form.addEventListener('change',update);
try{store=createDraftStore(window.localStorage);draft=store.load();inventory=createComponentStore(window.localStorage).list();for(const key of ['reference','channel','basePrice','packaging','labourRate','labourMinutes','feePercent','feeFixed'])field(key).value=draft[key]??defaultDraft()[key];populateRows();ready=true;render();$('#draft-status').textContent='Draft loaded. Changes save automatically in this browser.';}catch(error){$('#master-error').textContent=error.message;for(const input of form.querySelectorAll('input,select,button'))input.disabled=true;}
window.addEventListener('storage',e=>{if(!ready)return;if(e.key===storageKey){try{inventory=createComponentStore(window.localStorage).list();populateRows();render();}catch(error){$('#master-error').textContent=error.message;$('#master-results').hidden=true;}}if(e.key===draftKey)$('#draft-status').textContent='The draft changed in another tab. Reload to use that version before editing.';});
